import React, { useState, useRef } from 'react';

const Chat = () => {
  const [isRecording, setIsRecording] = useState(false);
  const [chatHistory, setChatHistory] = useState([]);
  const [error, setError] = useState('');
  const [audioHtml, setAudioHtml] = useState('');
  const mediaRecorderRef = useRef(null);

  // 시간을 "시:분" 형식으로 가져오는 함수
  const getTimeOnly = () => {
    const now = new Date();
    const hours = String(now.getHours()).padStart(2, '0');
    const minutes = String(now.getMinutes()).padStart(2, '0');
    return `${hours}:${minutes}`;
  };

  // 음성 녹음 시작
  const startRecording = async () => {
    if (isRecording) return;

    setIsRecording(true);
    const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    mediaRecorderRef.current = new MediaRecorder(stream);
    
    mediaRecorderRef.current.ondataavailable = (event) => {
      const audioData = event.data;
      handleAudioResponse(audioData);  // 서버로 음성 데이터를 전송하여 텍스트로 변환
    };
    
    mediaRecorderRef.current.start();
  };

  // 음성 녹음 중지
  const stopRecording = () => {
    if (mediaRecorderRef.current) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  // 서버에서 음성 변환 결과를 받아와서 처리
  const handleAudioResponse = async (audioData) => {
    try {
      const formData = new FormData();
      formData.append('file', new Blob([audioData]), 'audio.wav');

      const response = await fetch(`${process.env.REACT_APP_API_URL}/chat-audio`, {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || "오류가 발생했습니다.");
      }

      const data = await response.json();
      const { transcribed_text, response: chatbotMessage, audio_html } = data;  // 음성 텍스트와 챗봇 응답

      const receivedTime = getTimeOnly();  // 시:분만 추가
      setChatHistory((prevHistory) => [
        ...prevHistory,
        { sender: "사용자", message: transcribed_text, time: receivedTime },
      ]);

      setChatHistory((prevHistory) => [
        ...prevHistory,
        { sender: '챗봇', message: chatbotMessage, time: receivedTime },
      ]);

      // audioHtml은 음성 합성 결과에 사용될 수 있습니다.
      setAudioHtml(audio_html);

    } catch (error) {
      console.error("Error fetching chatbot response:", error);
      setError(error.message);
    }
  };

  return (
    <div>
      <h1>음성 인식 챗봇</h1>
      
      <button onClick={startRecording} disabled={isRecording}>녹음 시작</button>
      <button onClick={stopRecording} disabled={!isRecording}>녹음 중지</button>
      
      {error && <p style={{ color: 'red' }}>{error}</p>}

      <div>
        {chatHistory.map((entry, index) => (
          <div key={index} style={{ textAlign: entry.sender === '사용자' ? 'right' : 'left' }}>
            <p>{entry.time} - <strong>{entry.sender}:</strong> {entry.message}</p>
          </div>
        ))}
      </div>

      {/* 음성 처리 후 화면에 출력 */}
      {audioHtml && <div dangerouslySetInnerHTML={{ __html: audioHtml }} />}
    </div>
  );
};

export default Chat;
